selector_to_html = {"a[href=\"#flagtree-0-2-0\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree 0.2.0 \u53d1\u5e03<a class=\"headerlink\" href=\"#flagtree-0-2-0\" title=\"Link to this heading\">#</a></h1><h2>\u4eae\u70b9<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>FlagTree \u7ee7\u627f\u524d\u4e00\u7248\u672c\u7684\u80fd\u529b\uff0c\u6301\u7eed\u96c6\u6210\u65b0\u540e\u7aef\uff0c\u6269\u5c55 Triton \u7248\u672c\u652f\u6301\uff0c\u5e76\u63d0\u4f9b\u786c\u4ef6\u611f\u77e5\u4f18\u5316\u80fd\u529b\u3002\u9879\u76ee\u76ee\u524d\u5904\u4e8e\u65e9\u671f\u9636\u6bb5\uff0c\u65e8\u5728\u517c\u5bb9\u73b0\u6709\u5404 AI \u82af\u7247\u540e\u7aef\u7684\u9002\u914d\u65b9\u6848\uff0c\u7edf\u4e00\u4ee3\u7801\u4ed3\u5e93\uff0c\u6784\u5efa\u4ee3\u7801\u5171\u5efa\u5e73\u53f0\uff0c\u5feb\u901f\u5b9e\u73b0\u5355\u4ed3\u5e93\u591a\u540e\u7aef\u652f\u6301\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4eae\u70b9<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>FlagTree \u7ee7\u627f\u524d\u4e00\u7248\u672c\u7684\u80fd\u529b\uff0c\u6301\u7eed\u96c6\u6210\u65b0\u540e\u7aef\uff0c\u6269\u5c55 Triton \u7248\u672c\u652f\u6301\uff0c\u5e76\u63d0\u4f9b\u786c\u4ef6\u611f\u77e5\u4f18\u5316\u80fd\u529b\u3002\u9879\u76ee\u76ee\u524d\u5904\u4e8e\u65e9\u671f\u9636\u6bb5\uff0c\u65e8\u5728\u517c\u5bb9\u73b0\u6709\u5404 AI \u82af\u7247\u540e\u7aef\u7684\u9002\u914d\u65b9\u6848\uff0c\u7edf\u4e00\u4ee3\u7801\u4ed3\u5e93\uff0c\u6784\u5efa\u4ee3\u7801\u5171\u5efa\u5e73\u53f0\uff0c\u5feb\u901f\u5b9e\u73b0\u5355\u4ed3\u5e93\u591a\u540e\u7aef\u652f\u6301\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u65b0\u7279\u6027<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u76ee\u524d\u652f\u6301\u7684\u540e\u7aef\u5305\u62ec triton_shared cpu\u3001iluvatar\u3001xpu (klx)\u3001mthreads\u3001<strong>metax</strong>\u3001<strong>aipu</strong>(arm npu)\u3001<strong>ascend</strong> npu &amp; cpu\u3001<strong>tsingmicro</strong>\u3001cambricon\uff0c\u5176\u4e2d <strong>\u7c97\u4f53</strong> \u8868\u793a\u65b0\u589e\u3002<br/>\n\u6bcf\u4e2a\u65b0\u540e\u7aef\u5747\u4fdd\u6301\u524d\u4e00\u7248\u672c\u7684\u80fd\u529b\uff1a\u8de8\u5e73\u53f0\u7f16\u8bd1\u4e0e\u5feb\u901f\u9a8c\u8bc1\u3001\u57fa\u4e8e\u63d2\u4ef6\u7684\u9ad8\u5dee\u5f02\u6a21\u5757\u3001CI/CD \u548c\u8d28\u91cf\u7ba1\u7406\u80fd\u529b\u3002<br/>\n\u4e0e\u540e\u7aef\u5382\u5546\u8054\u5408\u5f00\u53d1\u4e2d\u95f4\u4ef6\u5c42\u7684\u901a\u7528\u6269\u5c55\uff0c\u5e76\u5f00\u6e90\u6807\u51c6\u5316\u7684 PyTorch \u540e\u7aef\u6269\u5c55\uff0c\u4ee5\u652f\u6301 Triton / FlagTree \u5b9e\u8df5\u3002<br/></p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5c55\u671b<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>GPGPU \u540e\u7aef\u4ee3\u7801\u5c06\u88ab\u6574\u5408\uff0c\u5c06\u540e\u7aef\u5dee\u5f02\u5316\u53d8\u66f4\u4e0e TritonGPU \u89e3\u8026\uff1b\u975e GPGPU \u540e\u7aef\u5c06\u5728 FLIR \u57fa\u7840\u4e0a\u8fdb\u884c\u6a2a\u5411\u6574\u5408\uff0c\u7edf\u4e00\u8bbe\u8ba1\u901a\u7528 pass\u3002<br/>\n\u4e3a\u540e\u7aef\u5382\u5546\u63d0\u4f9b Triton \u9002\u914d\u7248\u672c\u5347\u7ea7\u6307\u5357\uff1a3.0 -&gt; 3.1 -&gt; 3.2 -&gt; 3.3\u3002<br/>\nCI/CD \u5c06\u65b0\u589e FlagGems \u7b97\u5b50\u5e93\u529f\u80fd\u6d4b\u8bd5\u3002<br/>\n\u96c6\u6210 C++ Runtime \u529f\u80fd\uff0c\u964d\u4f4e kernel \u4e4b\u5916\u7684\u8fd0\u884c\u65f6\u5f00\u9500\uff0c\u4f7f\u5176\u4e0e CUDA \u6301\u5e73\u3002<br/></p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
